import Foundation
import XCTest
@testable import ColorComposerCore

/// Replays the solver parity corpus committed from the `color_matching`
/// backend (`priv/parity/v1/corpus.json`, upstream issue #111).
///
/// The corpus is generated by the Elixir `ColorMatching.WeightedSquaredError`
/// scorer with the `IlluminantMatching` earliest-index-wins selection policy,
/// and is the shared source of truth for client/server parity. Every scenario
/// must reproduce exactly — per-candidate scores, missing-measurement
/// exclusions, selected index, and tie evidence — so silent divergence of
/// `WeightedSquaredErrorScorer` is caught here.
///
/// The corpus lives at `Fixtures/solver-parity-corpus.json`; see
/// `docs/solver-parity-corpus.md` for where it comes from and how to
/// refresh it.
final class SolverParityCorpusTests: XCTestCase {

    // MARK: - Corpus contract

    func testCorpusMetadataMatchesClientSolverContract() throws {
        let corpus = try loadCorpus()
        XCTAssertEqual(corpus.algorithmVersion, 1, "scoring semantics moved; refresh the corpus and review parity")
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(Set(corpus.lightSources), Set(LightingCondition.all.map(\.rawValue)))
    }

    func testCorpusCoversTieExclusionAndWeightingScenarios() throws {
        let corpus = try loadCorpus()
        let ids = Set(corpus.scenarios.map(\.id))
        for required in [
            "tie-symmetric-around-target", "tie-duplicate-vectors", "tie-three-way-on-lps",
            "missing-candidate-excluded", "missing-target-excluded", "all-excluded",
            "zero-weight-channel-missing", "unknown-weight-ignored"
        ] {
            XCTAssertTrue(ids.contains(required), "corpus is missing scenario \(required); refresh the fixture")
        }
    }

    // MARK: - Scorer parity

    /// Every candidate score in every scenario must match the Elixir-computed
    /// expectation exactly. Corpus values are dyadic rationals, so any real
    /// divergence is a floating-point-order or policy change, not noise.
    func testScorerReproducesEveryCandidateScoreExactly() throws {
        let corpus = try loadCorpus()
        for scenario in corpus.scenarios {
            let palette = scenario.palette.map(makeColor)
            let target = makeTarget(scenario.target)
            let weights = makeWeights(scenario.weights)

            for entry in scenario.expected.scores {
                let result = WeightedSquaredErrorScorer().score(
                    candidate: palette[entry.index], target: target, weights: weights
                )
                switch (result, entry.score) {
                case (.excluded, .excluded):
                    break
                case (.score(let value), .value(let expected)):
                    XCTAssertEqual(value, expected, "\(scenario.id): candidate \(entry.index) score diverged")
                default:
                    XCTFail("\(scenario.id): candidate \(entry.index) expected \(entry.score), got \(result)")
                }
            }
        }
    }

    /// Selection parity: lowest score wins, earliest index on exact ties —
    /// including the tie scenarios where a later duplicate must NOT win.
    func testEarliestWinsSelectionMatchesExpectedPicksIncludingTies() throws {
        for scenario in try loadCorpus().scenarios {
            let palette = scenario.palette.map(makeColor)
            let target = makeTarget(scenario.target)
            let weights = makeWeights(scenario.weights)
            let expected = scenario.expected

            let scored = palette.map { WeightedSquaredErrorScorer().score(candidate: $0, target: target, weights: weights) }
            let (bestIndex, bestScore) = Self.selectEarliestWin(scoring: scored)

            XCTAssertEqual(bestIndex, expected.selectedIndex, "\(scenario.id): selected index diverged")
            XCTAssertEqual(bestScore, expected.error, "\(scenario.id): winning error diverged")
            if let index = expected.selectedIndex {
                XCTAssertEqual(palette[index].hex, expected.selectedHexColor, "\(scenario.id): selected hex diverged")
            }

            let tied = Self.tiedIndices(scoring: scored, at: bestScore)
            XCTAssertEqual(tied, expected.tiedIndices, "\(scenario.id): tie membership diverged")
            XCTAssertEqual(tied.count > 1, expected.tieBroke ?? false, "\(scenario.id): tie_broke diverged")
        }
    }

    /// End-to-end parity through the production solver fast path on a 1×1
    /// grid, for every scenario whose target measures all active channels
    /// (a target missing an active channel cannot be expressed as a grid).
    func testCompositionSolverFastPathMatchesCorpusSelections() throws {
        for scenario in try loadCorpus().scenarios {
            let weights = makeWeights(scenario.weights)
            let active = weights.activeEntries
            guard active.allSatisfy({ scenario.target.channels[$0.condition.rawValue] != nil }) else { continue }

            var grids: [LightingCondition: BrightnessGrid] = [:]
            for (condition, _) in active {
                grids[condition] = BrightnessGrid(width: 1, height: 1, values: [scenario.target.channels[condition.rawValue]!])
            }

            let result = try CompositionSolver().solve(
                palette: scenario.palette.map(makeColor),
                sourceGrids: grids,
                weights: weights
            )

            XCTAssertEqual(result.colorIndex(x: 0, y: 0), scenario.expected.selectedIndex, "\(scenario.id)")
            if let expectedError = scenario.expected.error {
                XCTAssertEqual(result.error(x: 0, y: 0), expectedError, "\(scenario.id)")
            } else {
                XCTAssertTrue(result.error(x: 0, y: 0).isInfinite, "\(scenario.id): expected an unmatched cell")
            }
        }
    }

    // MARK: - Corpus loading

    private func loadCorpus() throws -> ParityCorpus {
        let fixtureURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/solver-parity-corpus.json")
        let data = try Data(contentsOf: fixtureURL)
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        return try decoder.decode(ParityCorpus.self, from: data)
    }

    private func makeWeights(_ raw: [String: Double]) -> ChannelWeights {
        func weight(_ condition: LightingCondition) -> Double { raw[condition.rawValue] ?? 0 }
        return ChannelWeights(
            white: weight(.white), red: weight(.red), green: weight(.green),
            blue: weight(.blue), lps: weight(.lps)
        )
    }

    private func makeColor(_ vector: ParityVector) -> PaletteColor {
        var responses: [LightingCondition: IlluminationResponse] = [:]
        for (key, value) in vector.channels {
            if let condition = LightingCondition(rawValue: key) {
                responses[condition] = IlluminationResponse(brightness: value)
            }
        }
        return PaletteColor(
            id: vector.index ?? 0,
            hex: vector.hexColor,
            rgb: RGBColor(hex: vector.hexColor)!,
            responses: responses
        )
    }

    private func makeTarget(_ vector: ParityVector) -> TargetResponseVector {
        var brightness: [LightingCondition: Double] = [:]
        for (key, value) in vector.channels {
            if let condition = LightingCondition(rawValue: key) {
                brightness[condition] = value
            }
        }
        return TargetResponseVector(brightness)
    }

    /// Mirrors `IlluminantMatching.best_match/4`: strictly-lower scores
    /// replace the incumbent, so equal scores keep the earliest index.
    private static func selectEarliestWin(scoring: [ScorerResult]) -> (index: Int?, score: Double?) {
        var bestIndex: Int?
        var bestScore: Double?
        for (index, result) in scoring.enumerated() {
            guard case .score(let value) = result else { continue }
            if bestScore == nil || value < bestScore! {
                bestScore = value
                bestIndex = index
            }
        }
        return (bestIndex, bestScore)
    }

    private static func tiedIndices(scoring: [ScorerResult], at bestScore: Double?) -> [Int] {
        guard let bestScore else { return [] }
        var indices: [Int] = []
        for (index, result) in scoring.enumerated() {
            if case .score(let value) = result, value == bestScore {
                indices.append(index)
            }
        }
        return indices
    }
}

// MARK: - Corpus wire model

private struct ParityCorpus: Decodable {
    let algorithmVersion: Int
    let scorer: String
    let selection: String
    let missingPolicy: String
    let lightSources: [String]
    let scenarios: [ParityScenario]
}

private struct ParityScenario: Decodable {
    let id: String
    let description: String
    let weights: [String: Double]
    let target: ParityVector
    let palette: [ParityVector]
    let expected: ParityExpected
}

private struct ParityVector: Decodable {
    let index: Int?
    let hexColor: String
    let channels: [String: Double]
}

private struct ParityExpected: Decodable {
    let scores: [ParityScoreEntry]
    let selectedIndex: Int?
    let selectedHexColor: String?
    let error: Double?
    let tieBroke: Bool?
    let tiedIndices: [Int]
}

private struct ParityScoreEntry: Decodable {
    let index: Int
    let score: ParityScore
}

/// A corpus score cell: a finite number, or the string `"excluded"`.
private enum ParityScore: Equatable, CustomStringConvertible {
    case value(Double)
    case excluded

    var description: String {
        switch self {
        case .value(let value): return "\(value)"
        case .excluded: return "excluded"
        }
    }
}

extension ParityScore: Decodable {
    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let string = try? container.decode(String.self), string == "excluded" {
            self = .excluded
        } else {
            self = .value(try container.decode(Double.self))
        }
    }
}
